final class TarFileSystemMutaGate7Test {
  @Test
  void provider_returnsCreatingProvider_andIsConsistentAcrossPathsAndCloseState() throws IOException {
    Path tarPath = Files.createTempFile("tarballfs-test-", ".tar");
    try {
      byte[] data = "hello".getBytes(StandardCharsets.UTF_8);
      try (OutputStream out = Files.newOutputStream(tarPath);
          TarArchiveOutputStream tarOut = new TarArchiveOutputStream(out)) {
        TarArchiveEntry entry = new TarArchiveEntry("hello.txt");
        entry.setSize(data.length);
        tarOut.putArchiveEntry(entry);
        tarOut.write(data);
        tarOut.closeArchiveEntry();
      }

      TarFileSystemProvider providerA = new TarFileSystemProvider();
      TarFileSystemProvider providerB = new TarFileSystemProvider();

      URI uriA = URI.create("tar:" + tarPath.toAbsolutePath());
      FileSystem fsA = providerA.newFileSystem(uriA, Map.of());
      FileSystem fsB = providerB.newFileSystem(tarPath, Map.of());
      try {
        assertNotNull(fsA.provider());
        assertSame(providerA, fsA.provider());
        assertSame(providerB, fsB.provider());
        assertSame(fsA.provider(), fsA.provider());

        // Paths report the same provider as their file system.
        assertSame(providerA, fsA.getPath("/hello.txt").getFileSystem().provider());
        assertEquals("tar", fsA.provider().getScheme());
      } finally {
        fsA.close();
        fsB.close();
      }

      // provider() remains available after close.
      assertSame(providerA, fsA.provider());
      assertSame(providerB, fsB.provider());
    } finally {
      Files.deleteIfExists(tarPath);
    }
  }
}

